item.command:
/run/current-system/sw/bin/bash -lc 'D="$PWD/.wikipedia-hyprland-recording"
END=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$D/raw.mp4")
awk -F'"'\\t' -v end=\""'$END" '"'
  function ts(x){ return sprintf(\"%02d:%02d:%02d,%03d\", x/3600, (x%3600)/60, x%60, (x-int(x))*1000) }
  { t[NR]="'$1; c[NR]=$2 }
  END { for (i=1;i<=NR;i++) printf "%d'"\\n%s --> %s\\n%s\\n\\n\", i, ts(t[i]), ts(i<NR ? t[i+1] : end), c[i] }
' \""'$D/captions.tsv" > "$D/captions.srt"
timeout 60s ffmpeg -hide_banner -loglevel warning -y -i "$D/raw.mp4" -vf "subtitles=$D/captions.srt:force_style='"'FontName=DejaVu Sans,FontSize=19,PrimaryColour=&H00FFFFFF,BackColour=&HBB000000,BorderStyle=4,Outline=0,Shadow=0,MarginV=25'\" -c:v libx264 -preset veryfast -crf 20 -pix_fmt yuv420p -movflags +faststart \""'$D/wikipedia-hyprland.mp4"'

